std::mt19937_64 rng(seed);
std::uniform_real_distribution<double> x_dist(a, b);
std::uniform_real_distribution<double> y_dist(0.0, fmax);

int hits = 0;
for (int i = 0; i < n_points; ++i) {
    double x = x_dist(rng);
    double y = y_dist(rng);
    if (y <= f(x)) {
        ++hits;
    }
}

return (b - a) * fmax * static_cast<double>(hits) / n_points;
// END_CODE

